def test_all_countries_present():
    assert sorted(batch.COUNTRIES) == COUNTRIES


@pytest.mark.parametrize("country", COUNTRIES)
def test_totals(country):
    assert batch.totals(country, GRID[::7]) == EXPECTED[country]["totals"]


@pytest.mark.parametrize("country", COUNTRIES)
def test_component_sums(country):
    assert batch.component_sums(country, GRID) == EXPECTED[country]["sums"]


@pytest.mark.parametrize("country", COUNTRIES)
@pytest.mark.parametrize("order", [[-1, 0, "general", False, 1], [0, -1, "general", False, 1],
                                   [0, 0, "toys", False, 1], [0, 0, "general", False, 4], [0, 0, "general", True, 0]])
def test_invalid_input(country, order):
    with pytest.raises(ValueError):
        batch.quotes(country, [order])
